import java.io.*;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) throws IOException {
        byte[] in = System.in.readAllBytes();
        int p = 0;
        long n = 0, w = 0;
        while (p < in.length && in[p] == ' ') p++;
        while (p < in.length && in[p] >= '0' && in[p] <= '9') n = n * 10 + (in[p++] - '0');
        while (p < in.length && in[p] == ' ') p++;
        while (p < in.length && in[p] >= '0' && in[p] <= '9') w = w * 10 + (in[p++] - '0');
        while (p < in.length && in[p] != '\n') p++;
        if (p < in.length) p++;
        int width = (int) w;
        byte[] border = new byte[width + 5];
        Arrays.fill(border, (byte) '-');
        border[0] = '+';
        border[width + 3] = '+';
        border[width + 4] = '\n';
        BufferedOutputStream out = new BufferedOutputStream(System.out, 1 << 16);
        byte[] row = new byte[width + 5];
        for (long i = 0; i < n; i++) {
            // A sentence is the whole line up to '\n', spaces included.
            int e = p;
            while (e < in.length && in[e] != '\n') e++;
            int len = e - p;
            Arrays.fill(row, (byte) ' ');
            row[0] = '|';
            System.arraycopy(in, p, row, 2, len);
            row[width + 3] = '|';
            row[width + 4] = '\n';
            out.write(border);
            out.write(row);
            p = e < in.length ? e + 1 : e;
        }
        if (n > 0) out.write(border);
        out.flush();
    }
}

package main

import (
	"bufio"
	"bytes"
	"io"
	"os"
)

func main() {
	in, _ := io.ReadAll(os.Stdin)
	p, n, w := 0, 0, 0
	for p < len(in) && in[p] == ' ' {
		p++
	}
	for p < len(in) && in[p] >= '0' && in[p] <= '9' {
		n = n*10 + int(in[p]-'0')
		p++
	}
	for p < len(in) && in[p] == ' ' {
		p++
	}
	for p < len(in) && in[p] >= '0' && in[p] <= '9' {
		w = w*10 + int(in[p]-'0')
		p++
	}
	for p < len(in) && in[p] != '\n' {
		p++
	}
	if p < len(in) {
		p++
	}
	border := []byte("+" + string(bytes.Repeat([]byte("-"), w+2)) + "+\n")
	out := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer out.Flush()
	spaces := bytes.Repeat([]byte(" "), w)
	for i := 0; i < n; i++ {
		// A sentence is the whole line up to '\n', spaces included.
		e := p
		for e < len(in) && in[e] != '\n' {
			e++
		}
		out.Write(border)
		out.WriteString("| ")
		out.Write(in[p:e])
		out.Write(spaces[:w-(e-p)])
		out.WriteString(" |\n")
		if e < len(in) {
			p = e + 1
		} else {
			p = e
		}
	}
	if n > 0 {
		out.Write(border)
	}
}
